create extension if not exists pgcrypto;
create table if not exists events(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,starts_at timestamptz not null,venue text,address text,dress_code text,maps_url text,card_image text,active boolean default true);
create table if not exists invitations(id uuid primary key default gen_random_uuid(),token text unique not null default upper(substr(encode(gen_random_bytes(8),'hex'),1,10)),primary_name text not null,email text not null,phone text,category text default 'Friends');
create table if not exists invitation_events(invitation_id uuid references invitations on delete cascade,event_id uuid references events on delete cascade,primary key(invitation_id,event_id));
create table if not exists rsvps(id uuid primary key default gen_random_uuid(),invitation_id uuid unique references invitations on delete cascade,primary_name text,email text,phone text,adults int check(adults between 1 and 20),children int check(children between 0 and 20),guest_names text[],notes text,updated_at timestamptz default now());
create table if not exists rsvp_events(rsvp_id uuid references rsvps on delete cascade,event_id uuid references events on delete cascade,status text check(status in('yes','no')),primary key(rsvp_id,event_id));
alter table events enable row level security;alter table invitations enable row level security;alter table invitation_events enable row level security;alter table rsvps enable row level security;alter table rsvp_events enable row level security;
drop policy if exists "active events" on events;create policy "active events" on events for select using(active=true);drop policy if exists "admin invitations" on invitations;create policy "admin invitations" on invitations for all to authenticated using(true) with check(true);drop policy if exists "admin assignments" on invitation_events;create policy "admin assignments" on invitation_events for all to authenticated using(true) with check(true);drop policy if exists "admin rsvps" on rsvps;create policy "admin rsvps" on rsvps for all to authenticated using(true) with check(true);drop policy if exists "admin responses" on rsvp_events;create policy "admin responses" on rsvp_events for all to authenticated using(true) with check(true);
insert into events(slug,name,starts_at,venue,address,dress_code,maps_url,card_image) values('goyni','Goyni','2026-10-25 10:00 America/Toronto','Fadia Residence','67 Bermondsey Way, Brampton','Regular / Casual','https://www.google.com/maps/search/?api=1&query=67%20Bermondsey%20Way%20Brampton',null),('srimant','Srimant','2026-11-01 09:00 America/Toronto','Fadia Residence','67 Bermondsey Way, Brampton','Indian Traditional','https://www.google.com/maps/search/?api=1&query=67%20Bermondsey%20Way%20Brampton','./assets/invitations/srimant.png'),('baby-shower','Baby Shower','2026-11-01 17:00 America/Toronto','Professor''s Lake Recreation Centre','1660 N Park Dr, Brampton, ON L6S 4B4','Western Outfit','https://www.google.com/maps/search/?api=1&query=1660%20N%20Park%20Dr%20Brampton%20ON%20L6S%204B4','./assets/invitations/baby-shower.png') on conflict(slug) do update set name=excluded.name,starts_at=excluded.starts_at,venue=excluded.venue,address=excluded.address,dress_code=excluded.dress_code,maps_url=excluded.maps_url,card_image=excluded.card_image;
create or replace function get_invitation_by_token(p_token text) returns json language plpgsql security definer set search_path=public as $$declare i invitations;begin select * into i from invitations where upper(token)=upper(p_token);if i.id is null then return null;end if;return json_build_object('invitation',row_to_json(i),'events',(select coalesce(json_agg(e order by e.starts_at),'[]') from events e join invitation_events x on x.event_id=e.id where x.invitation_id=i.id),'rsvp',(select json_build_object('adults',r.adults,'children',r.children,'guest_names',r.guest_names,'notes',r.notes,'responses',(select coalesce(json_agg(json_build_object('event_id',z.event_id,'status',z.status)),'[]') from rsvp_events z where z.rsvp_id=r.id)) from rsvps r where r.invitation_id=i.id));end$$;grant execute on function get_invitation_by_token(text) to anon,authenticated;
create or replace function submit_rsvp(p_token text,p_primary_name text,p_email text,p_phone text,p_adults int,p_children int,p_guest_names text[],p_notes text,p_responses jsonb) returns void language plpgsql security definer set search_path=public as $$declare iid uuid;rid uuid;x jsonb;begin if now()>'2026-10-10 23:59:59 America/Toronto' then raise exception 'RSVP deadline has passed';end if;select id into iid from invitations where upper(token)=upper(p_token);if iid is null then raise exception 'Invalid invitation';end if;insert into rsvps(invitation_id,primary_name,email,phone,adults,children,guest_names,notes) values(iid,p_primary_name,p_email,p_phone,p_adults,p_children,p_guest_names,p_notes) on conflict(invitation_id) do update set primary_name=excluded.primary_name,email=excluded.email,phone=excluded.phone,adults=excluded.adults,children=excluded.children,guest_names=excluded.guest_names,notes=excluded.notes,updated_at=now() returning id into rid;delete from rsvp_events where rsvp_id=rid;for x in select * from jsonb_array_elements(p_responses) loop if exists(select 1 from invitation_events where invitation_id=iid and event_id=(x->>'event_id')::uuid) then insert into rsvp_events values(rid,(x->>'event_id')::uuid,x->>'status');end if;end loop;end$$;grant execute on function submit_rsvp(text,text,text,text,int,int,text[],text,jsonb) to anon,authenticated;